import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 현황 구분 값은 API 설명의 다섯 가지 이름을 그대로 쓴다.
const STATUS_TYPES = ['심사일자', '결의일자', '항목별', '지역별', '품단계'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function text(value: unknown): string {
  if (value === undefined || value === null) {
    return '';
  }
  return String(value).trim();
}

@Controller('api/v1')
export class FnSfr04204Controller {
  @Get('/fee-records/review-status')
  async listReviewStatuses(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '임직원');
    const query = checks.queryOf(req.query);

    const statusType = text(query['statusType']);
    const fromDate = text(query['fromDate']);
    const toDate = text(query['toDate']);
    const caseName = text(query['caseName']);

    if (statusType === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '현황 구분을 선택해 주세요.');
    }
    if (!STATUS_TYPES.includes(statusType)) {
      throw new ApiError(422, 'INVALID_SEARCH_CONDITION', '현황 구분이 올바르지 않습니다.');
    }
    if (fromDate !== '' && !DATE_PATTERN.test(fromDate)) {
      throw new ApiError(422, 'INVALID_SEARCH_CONDITION', '조회 시작일 형식이 올바르지 않습니다. (YYYY-MM-DD)');
    }
    if (toDate !== '' && !DATE_PATTERN.test(toDate)) {
      throw new ApiError(422, 'INVALID_SEARCH_CONDITION', '조회 종료일 형식이 올바르지 않습니다. (YYYY-MM-DD)');
    }
    if (fromDate !== '' && toDate !== '' && fromDate > toDate) {
      throw new ApiError(422, 'INVALID_SEARCH_CONDITION', '조회 시작일이 종료일보다 늦습니다.');
    }
    if (caseName.length > 200) {
      throw new ApiError(422, 'INVALID_SEARCH_CONDITION', '건명은 200자 이내로 입력해 주세요.');
    }

    const pageText = text(query['page']);
    const sizeText = text(query['size']);
    const page = pageText === '' ? 0 : Number(pageText);
    const size = sizeText === '' ? DEFAULT_SIZE : Number(sizeText);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'page는 0 이상의 정수여야 합니다.');
    }
    if (!Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'size는 1 이상의 정수여야 합니다.');
    }
    const limit = Math.min(size, MAX_SIZE);

    // 날짜 기준 열은 고정 문자열만 쓴다. 결의일자 현황은 결의서의 결의일자 기준이다.
    const dateColumn = statusType === '결의일자' ? 'er.resolution_date' : 'fr.registered_on';
    const conditions: string[] = ['1 = 1'];
    const params: Record<string, unknown> = {
      limit,
      offset: page * limit,
    };
    if (statusType === '결의일자') {
      conditions.push('er.expense_resolution_id IS NOT NULL');
    }
    if (fromDate !== '') {
      conditions.push(`${dateColumn} >= CAST(:fromDate AS date)`);
      params['fromDate'] = fromDate;
    }
    if (toDate !== '') {
      conditions.push(`${dateColumn} <= CAST(:toDate AS date)`);
      params['toDate'] = toDate;
    }
    if (caseName !== '') {
      conditions.push("fr.case_name ILIKE '%' || :caseName || '%'");
      params['caseName'] = caseName;
    }
    const where = conditions.join(' AND ');

    // 가정: 항목별은 수수료 구분 순으로 묶어 보이고, 그 밖의 구분은 기준 일자 최신순이다.
    let orderBy = `${dateColumn} DESC, fr.fee_record_id DESC`;
    if (statusType === '항목별') {
      orderBy = 'fr.fee_type, fr.registered_on DESC, fr.fee_record_id DESC';
    }

    return transaction(async (db) => {
      const countParams: Record<string, unknown> = { ...params };
      delete countParams['limit'];
      delete countParams['offset'];
      const countRows = await db.query(
        `SELECT COUNT(*) AS "total"
         FROM fee_record fr
         LEFT JOIN expense_resolution er ON er.expense_resolution_id = fr.expense_resolution_id
         WHERE ${where}`,
        countParams,
      );
      const total = Number(countRows[0]?.['total'] ?? 0);
      const items = await db.query(
        `SELECT fr.fee_record_id AS "feeRecordId",
                fr.case_no AS "caseNo",
                fr.case_name AS "caseName",
                fr.registered_on AS "registeredOn",
                fr.fee_amount AS "feeAmount"
         FROM fee_record fr
         LEFT JOIN expense_resolution er ON er.expense_resolution_id = fr.expense_resolution_id
         WHERE ${where}
         ORDER BY ${orderBy}
         LIMIT :limit OFFSET :offset`,
        params,
      );
      return { items, page, size: limit, total };
    });
  }
}

