import { useState } from 'react';
import {
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  Num,
  Pager,
  Pairs,
  Select,
  Tiles,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;
const STATUS_OPTIONS: [string, string][] = [
  ['심사일자', '심사일자'],
  ['결의일자', '결의일자'],
  ['항목별', '항목별'],
  ['지역별', '지역별'],
  ['품단계', '품단계'],
];

interface Condition {
  statusType: string;
  fromDate: string;
  toDate: string;
  caseName: string;
}

const EMPTY: Condition = { statusType: '', fromDate: '', toDate: '', caseName: '' };

export default function FnSfr04204Page({ role, notify }: PageProps) {
  const [form, setForm] = useState<Condition>(EMPTY);
  const [applied, setApplied] = useState<Condition | null>(null);
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [localError, setLocalError] = useState('');

  const { data, error, loading } = useData<Page>(async () => {
    if (applied === null) {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    return call<Page>('GET', '/fee-records/review-status', role, undefined, {
      statusType: applied.statusType,
      fromDate: applied.fromDate,
      toDate: applied.toDate,
      caseName: applied.caseName,
      page,
      size: SIZE,
    });
  }, [applied, page, role]);

  const rows = data?.items ?? [];
  const total = data?.total ?? 0;
  const pageSum = rows.reduce((sum, row) => sum + Number(row['feeAmount'] ?? 0), 0);

  function search() {
    if (form.statusType === '') {
      setLocalError('현황 구분을 선택해 주세요.');
      return;
    }
    if (form.fromDate !== '' && form.toDate !== '' && form.fromDate > form.toDate) {
      setLocalError('조회 시작일이 종료일보다 늦습니다.');
      return;
    }
    setLocalError('');
    setPage(0);
    setApplied({ ...form });
  }

  function reset() {
    setForm(EMPTY);
    setApplied(null);
    setLocalError('');
    setPage(0);
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 요약</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={total} />],
            ['현재 쪽 수수료 합계', <Num value={pageSum} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>심사현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="현황 구분" required>
            <Select
              value={form.statusType}
              onChange={(v) => setForm({ ...form, statusType: v })}
              options={STATUS_OPTIONS}
            />
          </Field>
          <Field label="조회 시작일">
            <DateInput value={form.fromDate} onChange={(v) => setForm({ ...form, fromDate: v })} />
          </Field>
          <Field label="조회 종료일">
            <DateInput value={form.toDate} onChange={(v) => setForm({ ...form, toDate: v })} />
          </Field>
          <Field label="건명">
            <TextInput value={form.caseName} onChange={(v) => setForm({ ...form, caseName: v })} />
          </Field>
        </Filters>
        {localError !== '' && <ErrorText text={localError} />}
        {error !== '' && <ErrorText text={error} />}
        <Band total={total} />
        <DataTable
          columns={[
            { key: 'caseNo', label: '건 번호' },
            { key: 'caseName', label: '건명' },
            { key: 'registeredOn', label: '등록일자', render: (r) => <DateText value={r['registeredOn']} /> },
            { key: 'feeAmount', label: '수수료 금액', render: (r) => <Num value={r['feeAmount']} /> },
          ]}
          rows={rows}
          onRowClick={(row) => setSelected(row)}
          empty={loading ? '불러오는 중입니다.' : applied === null ? '현황 구분을 선택하고 조회해 주세요.' : '조회 결과가 없습니다.'}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      {selected !== null && (
        <Drawer title="수수료 내역 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['수수료 내역 ID', String(selected['feeRecordId'] ?? '')],
              ['건 번호', String(selected['caseNo'] ?? '')],
              ['건명', String(selected['caseName'] ?? '')],
              ['등록일자', <DateText value={selected['registeredOn']} />],
              ['수수료 금액', <Num value={selected['feeAmount']} />],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
